/**
 * Skins generated by `zeste add`, in real Tailwind apps: Bits UI, Ark UI and shadcn-svelte with SvelteKit,
 * Radix, Ark UI and shadcn/ui with Next.js.
 * Same suite for each lib: server rendering, accessibility (axe), keyboard, preferences, compliance guard.
 */
import AxeBuilder from '@axe-core/playwright';
import { expect, test, type Page } from '@playwright/test';

async function interceptThirdParties(page: Page) {
  const requests: string[] = [];
  await page.route(
    (url) => url.hostname !== 'localhost',
    (route) => {
      requests.push(route.request().url());
      const type = route.request().resourceType();
      return route.fulfill({
        status: 200,
        contentType: type === 'script' ? 'text/javascript' : 'text/html',
        body: type === 'document' ? '<!doctype html><title>tiers</title>' : '',
      });
    },
  );
  return requests;
}

/** compliance guard warnings emitted by the page. */
function complianceWarnings(page: Page) {
  const warnings: string[] = [];
  page.on('console', (message) => {
    if (message.type() === 'warning' && message.text().startsWith('[zeste/consent]')) warnings.push(message.text());
  });
  return warnings;
}

/**
 * Opens the page and waits for hydration: the buttons exist in the server HTML, but they only
 * work once JavaScript has loaded and the engine has started (it then publishes its manifest).
 */
async function open(page: Page, path = '/') {
  await page.goto(path);
  await page.waitForFunction(() => window.__zesteManifest?.length);
}

const banner = (page: Page) => page.getByRole('region', { name: 'Cookies' });
const dialog = (page: Page) => page.getByRole('dialog', { name: 'Panneau de gestion des cookies' });
/** Toggles a switch with the keyboard (same gesture for every lib, and checks keyboard access). */
async function toggle(page: Page, name: string | RegExp) {
  await dialog(page).getByRole('switch', { name }).focus();
  await page.keyboard.press('Space');
}

const youtubeIframe = (page: Page, testId: string) => page.locator(`[data-testid="${testId}"] iframe`);

async function expectNoSeriousA11yIssues(page: Page, include: string) {
  const { violations } = await new AxeBuilder({ page }).include(include).analyze();
  const serious = violations.filter((v) => v.impact === 'serious' || v.impact === 'critical');
  expect(serious.map((v) => `${v.id}: ${v.help} (${v.nodes.map((n) => n.target.join(' ')).join(', ')})`)).toEqual([]);
}

test('server rendering: the banner is in the HTML', async ({ request }) => {
  const html = await (await request.get('/')).text();
  expect(html).toContain('data-zeste-banner');
  expect(html).toContain('Tout refuser');
});

test('theme: the dark class is set from the server render and the skin adapts to it', async ({ page, request }, testInfo) => {
  const { theme, adaptsToDark } = testInfo.project.metadata as { theme: 'light' | 'dark'; adaptsToDark: boolean };
  const html = await (await request.get('/')).text();
  expect(html.includes('<html lang="fr" class="dark">')).toBe(theme === 'dark');

  await open(page);
  await expect(banner(page)).toBeVisible();
  // Banner background color with and without the `dark` class, on the same page.
  const [light, dark] = await banner(page).evaluate((el) => {
    const root = document.documentElement;
    const read = (isDark: boolean) => {
      root.classList.toggle('dark', isDark);
      return getComputedStyle(el).backgroundColor;
    };
    const initial = root.classList.contains('dark');
    const values = [read(false), read(true)];
    root.classList.toggle('dark', initial);
    return values;
  });
  if (adaptsToDark) expect(dark).not.toBe(light);
  else expect(dark).toBe(light);
});

test('banner: nothing is sent before consent, buttons of equal weight, accessible', async ({ page }) => {
  const requests = await interceptThirdParties(page);
  const warnings = complianceWarnings(page);
  await open(page);
  await expect(banner(page)).toBeVisible();

  const deny = banner(page).getByRole('button', { name: 'Tout refuser' });
  const accept = banner(page).getByRole('button', { name: 'Tout accepter' });
  const [d, a] = [await deny.boundingBox(), await accept.boundingBox()];
  expect(d!.height).toBe(a!.height);
  expect(await deny.evaluate((el) => getComputedStyle(el).fontSize)).toBe(
    await accept.evaluate((el) => getComputedStyle(el).fontSize),
  );

  await expectNoSeriousA11yIssues(page, '[data-zeste-banner]');
  await page.waitForTimeout(300);
  expect(requests).toEqual([]);
  expect(warnings).toEqual([]);
});

test('"Tout accepter" by keyboard: video rendered, banner closed', async ({ page }) => {
  await interceptThirdParties(page);
  await open(page);
  await banner(page).getByRole('button', { name: 'Tout accepter' }).focus();
  await page.keyboard.press('Enter');
  await expect(banner(page)).toBeHidden();
  await expect(youtubeIframe(page, 'video-1')).toHaveAttribute('src', /youtube-nocookie\.com\/embed\/dQw4w9WgXcQ/);
});

test('preferences: accessible dialog, nothing pre-checked, keyboard choices, remembered', async ({ page }) => {
  const requests = await interceptThirdParties(page);
  const warnings = complianceWarnings(page);
  await open(page);
  await banner(page).getByRole('button', { name: 'Personnaliser' }).click();

  await expect(dialog(page)).toBeVisible();
  await expect(dialog(page).getByRole('heading', { name: "Mesure d'audience" })).toBeVisible();
  await expect.poll(() => dialog(page).evaluate((el) => el.contains(document.activeElement))).toBe(true);

  const switches = dialog(page).getByRole('switch');
  await expect(switches.first()).toBeVisible();
  for (const s of await switches.all()) await expect(s).not.toBeChecked();
  await expectNoSeriousA11yIssues(page, '[role="dialog"]');

  await toggle(page, 'YouTube');
  await expect(dialog(page).getByRole('switch', { name: 'YouTube' })).toBeChecked();
  await dialog(page).getByRole('button', { name: 'Enregistrer' }).click();

  await expect(dialog(page)).toBeHidden();
  await expect(banner(page)).toBeHidden();
  await expect(youtubeIframe(page, 'video-1')).toBeVisible();
  await page.waitForTimeout(1500); // give the "permanent link" guard rail time to run
  expect(requests.filter((u) => /googletagmanager|matomo/.test(u))).toEqual([]);
  expect(warnings).toEqual([]);

  await page.getByRole('contentinfo').getByRole('button', { name: 'Gestion des services' }).click();
  await expect(dialog(page).getByRole('switch', { name: 'YouTube' })).toBeChecked();
  await expect(dialog(page).getByRole('switch', { name: /Google Analytics/ })).not.toBeChecked();
});

test('Escape closes the preferences without saving anything', async ({ page }) => {
  await interceptThirdParties(page);
  await open(page);
  await banner(page).getByRole('button', { name: 'Personnaliser' }).click();
  await toggle(page, 'YouTube');
  await page.keyboard.press('Escape');
  await expect(dialog(page)).toBeHidden();
  await expect(banner(page)).toBeVisible();
  await expect(youtubeIframe(page, 'video-1')).toHaveCount(0);
});

test('skin placeholder: "Autoriser YouTube" only accepts YouTube', async ({ page }) => {
  const requests = await interceptThirdParties(page);
  await open(page);
  await expect(page.getByTestId('video-1')).toHaveCount(0);
  await page.getByText('YouTube est désactivé.').waitFor();
  await page.getByRole('button', { name: 'Autoriser YouTube' }).click();
  await expect(youtubeIframe(page, 'video-1')).toBeVisible();
  await expect(banner(page)).toBeVisible();
  expect(requests.filter((u) => /googletagmanager|matomo/.test(u))).toEqual([]);
});

test('withdrawal from the preferences: the video becomes a placeholder again, reload offered', async ({ page }) => {
  await interceptThirdParties(page);
  await open(page);
  await banner(page).getByRole('button', { name: 'Tout accepter' }).click();
  await expect(youtubeIframe(page, 'video-1')).toBeVisible();

  await page.getByRole('contentinfo').getByRole('button', { name: 'Gestion des services' }).click();
  await toggle(page, 'YouTube');
  await toggle(page, /Google Analytics/);
  await dialog(page).getByRole('button', { name: 'Enregistrer' }).click();

  await expect(page.getByRole('button', { name: 'Autoriser YouTube' })).toBeVisible();
  await expect(page.getByRole('status').getByRole('button', { name: 'Recharger la page' })).toBeVisible();
});

test.describe('compliance guard (modified real rendering)', () => {
  /** Injects CSS once the HTML is parsed, before the app scripts run (hydration). */
  const injectCss = (page: Page, css: string) =>
    page.addInitScript((content) => {
      document.addEventListener('readystatechange', () => {
        if (document.readyState !== 'interactive') return;
        const style = document.createElement('style');
        style.textContent = content;
        document.head.append(style);
      });
    }, css);

  test('no warning on the skin as generated', async ({ page }) => {
    const warnings = complianceWarnings(page);
    await open(page);
    await expect(banner(page)).toBeVisible();
    await page.waitForTimeout(500);
    expect(warnings).toEqual([]);
  });

  test('shrunken "Tout refuser" → warning', async ({ page }) => {
    const warnings = complianceWarnings(page);
    await injectCss(page, '[data-zeste-action="denyAll"] { font-size: 9px !important; padding: 0 !important; }');
    await open(page);
    await expect.poll(() => warnings.join('\n')).toContain('much smaller than "Accept all"');
  });

  for (const [format, color] of [
    ['hex', '#e7e5e4'],
    ['oklch (format Tailwind v4)', 'oklch(0.923 0.003 48.717)'],
  ]) {
    test(`unreadable "Tout refuser", ${format} color → warning`, async ({ page }) => {
      const warnings = complianceWarnings(page);
      // very light text on a white background: unreadable whatever the skin style
      await injectCss(page, `[data-zeste-action="denyAll"] { color: ${color} !important; background: #fff !important; }`);
      await open(page);
      await expect.poll(() => warnings.join('\n')).toContain('hard to read');
    });
  }

  test('no way left to reopen the preferences → warning', async ({ page }) => {
    await interceptThirdParties(page);
    const warnings = complianceWarnings(page);
    await open(page);
    await page.getByRole('contentinfo').evaluate((el) => el.remove());
    await banner(page).getByRole('button', { name: 'Tout refuser' }).click();
    await expect.poll(() => warnings.join('\n'), { timeout: 5000 }).toContain('reopen the preferences');
  });
});
